// The medication × weather safety dataset, loaded onto the curated-dataset framework
// (issue #1727). Copies the ototoxic.ts / dental-safety.ts shape: import the envelope
// JSON (generated by scripts/gen-weather-med-safety.ts), validate it once with
// loadDataset(), and expose the entries (photosensitizing and heat-risk drug concepts,
// matched by RxCUI ingredient + synonym) the cross-check consumes. Identity is the
// concept `key` token (fieldStrategy "key"). The registry lists this for the linter;
// lib/weather-med-safety.ts is the DOMAIN cross-check. Pure — no DB, no network.

import rawWeatherMed from "./data/weather-med-safety.json";
import { loadDataset } from "./loader";
import { fieldStrategy } from "./matcher";
import type {
  WeatherMedEntry,
  WeatherMedMeta,
} from "@/scripts/gen-weather-med-safety";

export type {
  WeatherMedEntry,
  WeatherMedMeta,
  WeatherExposure,
} from "@/scripts/gen-weather-med-safety";

// The validated dataset (envelope + guarantees). Throws at module load if the committed
// JSON ever violates the contract — a loud, early failure.
export const weatherMedSafetyDataset = loadDataset<
  WeatherMedEntry,
  WeatherMedMeta
>(rawWeatherMed);

// Identity strategy: the concept `key` token, case-folded. For the linter.
export const weatherMedKeyStrategy = fieldStrategy("key");

// The drug-concept entries the cross-check consumes.
export const WEATHER_MED_ENTRIES: WeatherMedEntry[] =
  weatherMedSafetyDataset.entries;
